pitfalls.badSnippet:
// Fires indefinitely in background even after navigating away
function draw() {
  offset = Math.max(0, offset - speed);
  requestAnimationFrame(draw);
}
draw();

pitfalls.goodSnippet:
// Cache rAF integer handle and cancel on unmount / teardown
let animId;
function draw() {
  offset = Math.max(0, offset - speed);
  animId = requestAnimationFrame(draw);
}
draw();
// Cleanup: cancelAnimationFrame(animId);

pitfalls.badSnippet:
// Does not clear canvas; frames accumulate over time
function draw() {
  ctx.stroke();
  requestAnimationFrame(draw);
}

pitfalls.goodSnippet:
// Always clear or fill the full canvas bounds before each frame draw
function draw() {
  ctx.fillRect(0, 0, width, height);
  ctx.stroke();
  requestAnimationFrame(draw);
}
